// Entry point for Cloudflare Workers: the OpenNext fetch handler plus an
// hourly scheduled job that keeps the Instagram token and feed fresh.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

import { rebuildSnapshot, refreshTokenIfDue, type InstagramEnv } from "./src/lib/instagram-store";

const worker = {
  // One canonical address: www.hemangbuilds.com redirects to hemangbuilds.com.
  async fetch(request: Request, env: unknown, ctx: ExecutionContext) {
    const url = new URL(request.url);
    if (url.hostname === "www.hemangbuilds.com") {
      url.hostname = "hemangbuilds.com";
      return Response.redirect(url.toString(), 301);
    }
    return handler.fetch(request, env, ctx);
  },

  async scheduled(_event: ScheduledController, env: InstagramEnv, ctx: ExecutionContext) {
    ctx.waitUntil(
      (async () => {
        const token = await refreshTokenIfDue(env);
        const snapshot = await rebuildSnapshot(env);
        console.log(
          `[instagram cron] ${token}; snapshot ${snapshot ? `${snapshot.posts.length} posts` : "not rebuilt"}`,
        );
      })(),
    );
  },
};

export default worker;
